[824]={["atomIDs"]={"824:description:1-90","824:description:93-198","824:description:203-270","824:description:273-372","824:description:375-438","824:objective:1-81"},["opening"]="Mastok directed the strange water globe to Je'neu Sancrea at Zoram'gar. The Earthen Ring's study of the elements and old lore might give the disturbing specimen a meaning that Mastok could not supply.",["pending"]="{actor} would show the Befouled Water Globe to Je'neu Sancrea.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered the Befouled Water Globe to Je'neu Sancrea.",["sourceHash"]="ec1a1ac29fb71a443e612df9140fbdfb0ba5b606f4df3543cb02e0a4f4d84539",["sourceRaceMask"]="178",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[825]={["aftermath"]="Gar'Thok planned to send the tools to Orgrimmar with the next caravan.",["atomIDs"]={"825:description:1-157","825:description:162-296","825:description:298-364","825:description:366-425","825:description:430-506","825:objective:1-93"},["endingAtomIDs"]={"825:completion:1-40","825:completion:42-114","825:completion:119-130"},["opening"]="Scouts had located wreckage from Proudmoore's fleet east of Tiragarde. Gar'Thok wanted gnomish tools recovered to study Alliance mechanics.",["pending"]="{actor} planned to retrieve three tools from the wreckage.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} brought the gnomish tools to Gar'Thok.",["sourceHash"]="f3d300e92d95dae8e276988d91548bc9eb3aa22d0ca8f849d2940e48469517ac",["sourceRaceMask"]="178",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[826]={["atomIDs"]={"826:description:1-62","826:description:65-103","826:description:108-210","826:description:215-233","826:description:238-312","826:description:315-374","826:objective:1-16","826:objective:21-60","826:objective:65-96"},["opening"]="Zalazane ruled from the Darkspear's former island home. Gadrin said his followers raided the mainland and brought more trolls under his hexes.",["pending"]="{actor} planned to confront Zalazane and his hexed followers.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} returned Zalazane's head after fulfilling Gadrin's assignment.",["sourceHash"]="a69ba6903cf8683881ed2ee7b5b33b9f5cc1e7219d493a111d68fa6949f0be85",["sourceRaceMask"]="178",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[827]={["atomIDs"]={"827:description:6-83","827:description:86-175","827:description:180-263","827:description:266-335","827:description:340-416","827:description:419-469","827:objective:1-55","827:objective:60-92"},["bridge"]="Burning collars worn in Skull Rock suggested a means of attuning the cultists to demonic power. Margoz needed examples before he could establish what they did.",["bridgeFrom"]=828,["bridgeReplacesSetup"]=true,["opening"]="Margoz suspected the burning collars in Skull Rock attuned cultists to demonic power. He needed examples before he could confirm their purpose.",["pending"]="{actor} planned to gather searing collars for Margoz.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered the collars from Skull Rock.",["sourceHash"]="1fbe49fd85177385f2cb33fa91b425982780e5bb4ec8755df945ff79a45e3301",["sourceRaceMask"]="178",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[828]={["atomIDs"]={"828:description:1-73","828:description:76-155","828:description:157-211","828:description:216-261","828:description:264-300","828:description:305-373","828:description:378-467","828:objective:1-18"},["bridge"]="The trail then turned to Margoz, whose knowledge might prepare a strike against Skull Rock. His camp lay between the coast and Drygulch Ravine.",["bridgeFrom"]=806,["bridgeReplacesSetup"]=true,["opening"]="Orgnil directed the investigation toward Margoz, whose knowledge might prepare a strike at Skull Rock. The shaman camped between the coast and Drygulch Ravine.",["pending"]="{actor} planned to seek Margoz's counsel.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} met Margoz at his camp.",["sourceHash"]="89fc29ffd99452c6e5fbab8cfeefa02a9a1394b077fc48f120a945c92fbefc61",["sourceRaceMask"]="178",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[829]={["atomIDs"]={"829:description:1-68","829:description:71-137","829:description:140-176","829:description:181-221","829:description:224-354","829:description:357-435","829:description:440-494","829:objective:1-56"},["bridge"]="The collars exceeded the shaman's knowledge. Neeru Fireblade in Orgrimmar offered another interpretation, though Margoz did not treat the warlock's claims of harmless research as settled truth.",["bridgeFrom"]=827,["bridgeReplacesSetup"]=true,["opening"]="The collars exceeded Margoz's skill to interpret. He turned to Neeru, a warlock whose claims of benign research Margoz left explicitly uncertain.",["pending"]="{actor} meant to take an example collar to Neeru.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered the collar in the Cleft of Shadow.",["sourceHash"]="87acffff1e59deb2081d3fbcdfdb8c86bc0de5fe1036e1f9a161861bb0e8371c",["sourceRaceMask"]="178",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[830]={["atomIDs"]={"830:description:1-83","830:description:85-129","830:description:134-154","830:description:156-249","830:objective:1-59"},["opening"]="A weathered envelope bore Proudmoore's seal and contained official orders. Gar'Thok, commanding at Razor Hill, might recognize their importance.",["pending"]="{actor} meant to take the admiral's orders to Gar'Thok.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered the recovered orders to Gar'Thok.",["sourceHash"]="d8c91ad1c6c9b049cb3a6e3f07c5c330998236adfef38aaf9c5a225a1f5c0e60",["sourceRaceMask"]="178",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[831]={["aftermath"]="Nazgrel prepared to counsel Thrall about the information.",["atomIDs"]={"831:description:1-25","831:description:27-108","831:description:113-183","831:description:185-257","831:description:262-309","831:description:311-403","831:description:408-471","831:description:473-508","831:objective:1-80"},["endingAtomIDs"]={"831:completion:1-110","831:completion:115-160","831:completion:165-228"},["opening"]="Gar'Thok read the orders as evidence that Proudmoore's plans survived the admiral. He sent the warning to Nazgrel in Thrall's chamber.",["pending"]="{actor} meant to carry the orders to Nazgrel.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered Proudmoore's orders in Orgrimmar.",["sourceHash"]="99d65730e6fdabdda64637e1dc8738f9814a21c9f9c727f57b45abafa3962d50",["sourceRaceMask"]="178",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[832]={["aftermath"]="Neeru called the reference to himself strange and undertook further study of the pendant.",["atomIDs"]={"832:description:1-52","832:description:57-64","832:description:69-85","832:description:90-135","832:description:138-168","832:description:173-202","832:description:205-318","832:description:323-362","832:description:367-395","832:objective:1-33"},["endingAtomIDs"]={"832:completion:1-36","832:completion:41-51","832:completion:53-90","832:completion:92-187","832:completion:189-303","832:completion:308-333","832:completion:335-395","832:completion:400-447","832:completion:449-490"},["opening"]="A voice from the pendant demanded that Gazz'uz report. Its threat invoked Neeru by name, giving the message a connection to investigate.",["pending"]="{actor} meant to bring the speaking eye to Neeru.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} placed the eye before Neeru.",["sourceHash"]="e68914b52bab0640f4e073a927f2534c36789768391e2219cb22077c72b132ab",["sourceRaceMask"]="178",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[833]={["atomIDs"]={"833:description:1-85","833:description:87-265","833:description:270-334","833:description:336-450","833:description:455-493","833:objective:1-78"},["opening"]="Red Rocks held the honored dead of Thunder Bluff's founding and defense. Raintotem was too old to drive the Bristleback interlopers from the burial ground.",["pending"]="{actor} planned to drive eight interlopers from Red Rocks.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} completed Raintotem's burial-ground assignment.",["sourceHash"]="f9872148b2974728380e24dbd13a3b276a45dd07873d32c1700720381eb5751f",["sourceRaceMask"]="178",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[834]={["atomIDs"]={"834:description:1-34","834:description:36-81","834:description:83-131","834:description:133-163","834:description:165-203","834:description:208-333","834:description:338-397","834:description:399-509","834:objective:1-70"},["opening"]="Rezlak came to help Gazlowe's work in Durotar, but caravan losses had stalled him. Dustwind harpies carried the latest shipment into the canyon.",["pending"]="{actor} planned to recover five sacks of supplies.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} returned Rezlak's stolen supplies.",["sourceHash"]="e5b5c788f2c2d86b416e43c86d648f4957a8bb3f4808d793283f220bd101ebc2",["sourceRaceMask"]="178",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[835]={["atomIDs"]={"835:description:1-30","835:description:32-135","835:description:140-234","835:description:236-301","835:description:303-360","835:description:365-506","835:objective:1-86"},["editorialNotes"]={"Standalone context never assumes that quest834 was previously completed."},["opening"]="Rezlak was losing supply caravans to the Dustwind harpies. He wanted their savages and storm witches driven back from Drygulch Ravine so that later shipments could reach Durotar.",["pending"]="{actor} planned to confront the ravine's savages and storm witches.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor}'s success left Rezlak hopeful about the next supply caravan.",["sourceHash"]="0ab279a27f24388a765ddd1fb3718a0fd1d36ad818cdcdfae6ba37b79f4f09db",["sourceRaceMask"]="178",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[836]={["aftermath"]="Oglethorpe credited the recovery with saving substantial rebuilding time while acknowledging that the series still needed development.",["atomIDs"]={"836:description:1-53","836:description:58-151","836:description:154-234","836:description:237-330","836:description:333-403","836:description:408-477","836:description:480-507","836:objective:1-106"},["endingAtomIDs"]={"836:completion:1-41","836:completion:43-103","836:completion:105-273","836:completion:278-331","836:completion:333-414"},["opening"]="Oglethorpe needed an open shoreline for the robot's lengthy departure procedure. Escorting it beyond Overlook Cliff would also buy time to restore its cloaking system.",["pending"]="{actor} intended to guard the robot's path to the shore.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} completed the escort and reported to Oglethorpe.",["sourceHash"]="5d472bc2c490072ea45b99f5706d2a179c352dd5cd1950e3370edcbb1bc9dc85",["sourceRaceMask"]="?",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[838]={["aftermath"]="Dithers believed he knew how to secure unrestricted passage through the front door, while warning that the work would be difficult.",["atomIDs"]={"838:description:1-101","838:description:104-191","838:description:194-277","838:description:282-367","838:description:370-469","838:description:472-501","838:objective:1-66"},["endingAtomIDs"]={"838:completion:1-92","838:completion:94-268","838:completion:273-326","838:completion:328-386"},["opening"]="A locked door protected Scholomance's research stronghold on Caer Darrow. Derrington entrusted the problem of entry to Dithers, whose studies suggested a way to obtain a key.",["pending"]="{actor} intended to discuss the key with Dithers.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} consulted the apothecary.",["sourceHash"]="b55d44971e2b2527e33a315be011ab316d9861a0978433c1a4c979ce02e6436c",["sourceRaceMask"]="178",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[840]={["aftermath"]="Kargal signed the letter and identified the Crossroads as the place most in need of help.",["atomIDs"]={"840:description:1-28","840:description:33-103","840:description:105-153","840:description:155-180","840:description:185-248","840:objective:1-69","840:objective:74-115","840:objective:120-189"},["endingAtomIDs"]={"840:completion:1-23","840:completion:25-86","840:completion:91-178"},["opening"]="Takrin saw another recruit for Barrens duty. His friend Kargal had to first sign the letter at the outpost across the western bridge.",["pending"]="{actor} planned to present the recruitment letter to Kargal.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} reached Kargal with the letter.",["sourceHash"]="2c3d8c00d4f11155299b0224d5aa6328d057d765a672824d39871be2310e07ed",["sourceRaceMask"]="178",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[841]={["aftermath"]="Bilgewhizzle supplied another power source and urged proper use. His taunts did not establish how the earlier source had been lost or exhausted.",["atomIDs"]={"841:description:1-96","841:description:99-122","841:description:124-150","841:description:153-233","841:description:236-311","841:description:316-385","841:description:388-413","841:description:416-457","841:objective:1-116"},["endingAtomIDs"]={"841:completion:1-40","841:completion:42-171"},["opening"]="Bilgewhizzle offered replacement power sources at a steeper price. This time he demanded ten Wastewander water pouches, twice the first exchange.",["pending"]="{actor} planned to exchange ten Wastewander Water Pouches for another power source.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} completed the ten-pouch exchange with Chief Engineer Bilgewhizzle.",["sourceClassMask"]="?",["sourceHash"]="e8f8b6948678df97abf7f9db1f988ff122eb0dde7e99af2daeac459a35f9facd",["sourceRaceMask"]="178",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
