[845]={["atomIDs"]={"845:description:1-103","845:description:106-224","845:description:229-293","845:description:296-370","845:objective:1-86"},["opening"]="Sergra raised the hunting test from plainstriders to zhevra. Their strength offered another step before she sent a recruit after larger prey.",["pending"]="{actor} planned to collect four zhevra hooves.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} returned the hooves to Sergra.",["sourceHash"]="25f16d600e1fe4aee38952dd9aca73b84c04d3cf8e3413e18ed795533b9370d0",["sourceRaceMask"]="178",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[846]={["atomIDs"]={"846:description:1-99","846:description:101-146","846:description:151-207","846:description:209-329","846:description:331-409","846:description:414-454","846:description:456-509","846:objective:1-121"},["bridge"]="The prospector's plans now shaped Gann's next attack. Expecting the dwarves to replace Khazgorm, he wanted their own supplies turned into a charge against the operation.",["bridgeAtomIDs"]={"846:description:1-99","846:description:101-146","846:description:151-207","846:description:209-329","846:description:331-409","846:description:414-454","846:description:456-509","846:objective:1-121"},["bridgeFrom"]=843,["bridgeMinimumStage"]=2,["bridgeReplacesSetup"]=true,["bridgeSourceHash"]="16d0af1731f3c22e2d576a05795279f662ff0a9e46feae05c272e2408d3b2fd0",["opening"]="Khazgorm's plans revealed the explosives and machines behind the digging. Gann intended to turn those same supplies against the dwarven operation.",["pending"]="{actor} planned to collect the three kinds of explosive materials.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} supplied Gann with the requested materials.",["sourceHash"]="16d0af1731f3c22e2d576a05795279f662ff0a9e46feae05c272e2408d3b2fd0",["sourceRaceMask"]="178",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[847]={["aftermath"]="Tor'gan planned a conversation once the enchantment wore off.",["atomIDs"]={"847:description:1-7","847:description:9-22","847:description:24-86","847:description:88-117","847:description:119-158","847:description:160-178","847:description:180-215","847:objective:1-19"},["endingAtomIDs"]={"847:completion:1-58","847:completion:60-137","847:completion:139-184"},["opening"]="The orb had caught Gor'mul's attention. He agreed, for the time being, to hear Tor'gan's explanation of the power he had felt.",["pending"]="{actor} intended to carry that agreement to Tor'gan.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} reported Gor'mul's willingness to listen.",["sourceHash"]="5934459767c68e3787b186d3ef03ff8e2b3db33809331cc7ff35b92ed4b86594",["sourceRaceMask"]="178",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[849]={["atomIDs"]={"849:description:1-81","849:description:86-101","849:description:106-160","849:description:162-242","849:description:247-351","849:description:353-432","849:description:437-507","849:objective:1-71"},["bridge"]="Gann directed the explosive toward the flying machine. It was equipment and a weapon of war, but also the image of a power he regarded as an insult to his tribe's memory.",["bridgeAtomIDs"]={"849:description:1-81","849:description:86-101","849:description:106-160","849:description:162-242","849:description:247-351","849:description:353-432","849:description:437-507","849:objective:1-71"},["bridgeFrom"]=846,["bridgeMinimumStage"]=2,["bridgeReplacesSetup"]=true,["bridgeSourceHash"]="5d31a6d4c46f6e386b3774c784bd1c8ce43af5dad4ba06bbff51c2dd446daaee",["opening"]="Gann had fashioned a charge from Khazgorm's plans. He targeted Bael Modan's flying machine as both infrastructure and an emblem of his tribe's dispossession.",["pending"]="{actor} planned to destroy the Bael Modan flying machine.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} completed the demolition and reported to Gann.",["sourceHash"]="5d31a6d4c46f6e386b3774c784bd1c8ce43af5dad4ba06bbff51c2dd446daaee",["sourceRaceMask"]="178",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
