[851]={["atomIDs"]={"851:description:1-81","851:description:84-166","851:description:169-206","851:description:211-297","851:description:300-388","851:description:391-410","851:description:415-474","851:objective:1-64"},["opening"]="Verog wandered too widely for an easy search. Regthar proposed drawing him out by attacking centaur near the Stagnant Oasis command tent.",["pending"]="{actor} meant to find Verog and bring back his head.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} returned Verog's head to Regthar.",["sourceHash"]="d58817d8dcb606a2d1c813dc883592350deac925877ad7bf5bc7220e9a5443d1",["sourceRaceMask"]="178",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
