[863]={["aftermath"]="Sputtervalve planned a salvage team for the wrecked prototype, hoping something valuable could still be recovered.",["atomIDs"]={"863:description:1-32","863:description:34-54","863:description:56-100","863:description:102-127","863:objective:1-89"},["endingAtomIDs"]={"863:completion:1-88","863:completion:90-111","863:completion:113-181","863:completion:186-237"},["opening"]="Wizzlecrank was prepared to learn the stolen shredder's controls during the escape. The machine and its uncertain operator needed protection on the way to Ratchet.",["pending"]="{actor} planned to escort Wizzlecrank and the shredder.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} completed the escort and reported to Sputtervalve.",["sourceHash"]="6ac4e922c734f751928c310d2c611cd74fabfcee40f10e4ed4e50c5c2f0ff28d",["sourceRaceMask"]="?",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[864]={["aftermath"]="Zinge prepared immediate analysis and hoped to make her own success from Keever's research.",["atomIDs"]={"864:description:1-75","864:description:78-110","864:description:113-178","864:description:183-269","864:description:272-343","864:description:346-415","864:objective:1-72"},["endingAtomIDs"]={"864:completion:1-37","864:completion:39-101","864:completion:106-118","864:completion:120-189","864:completion:191-264","864:completion:269-374"},["opening"]="Bilgewhizzle had removed the power source without losing the data. The sealed equipment was ready for the long return to the researcher waiting in the Undercity.",["pending"]="{actor} intended to bring the testing kit back to Zinge.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered the preserved field results.",["sourceHash"]="f7ff7b5f8e8e43437b12f9e4dfb9286e22dc054ea6841dcab2d5c831605ea18a",["sourceRaceMask"]="178",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
