[923]={["atomIDs"]={"923:description:1-50","923:description:53-190","923:description:193-270","923:description:273-293","923:description:298-383","923:description:386-435","923:objective:1-56"},["opening"]="Rellian saw malevolence growing in the timberlings but had not found its source. He considered those around northern Wellspring Lake beyond help and wanted their mossy tumors removed for burning.",["pending"]="{actor} meant to recover five Mossy Tumors for Rellian.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered five Mossy Tumors to Rellian Greenspyre.",["sourceHash"]="8cbbd2a1a722ba2c95d43464efeb99a3907b71e95fa6ee97c0dc75d7cbe782a9",["sourceRaceMask"]="77",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[924]={["aftermath"]="Ak'Zeloth confirmed the seed's destruction but warned that its release of power might have drawn other beings' attention.",["atomIDs"]={"924:description:1-57","924:description:59-126","924:description:131-232","924:description:237-318","924:description:320-363","924:description:365-394","924:description:396-447","924:description:452-508","924:objective:1-26","924:objective:29-109"},["endingAtomIDs"]={"924:completion:1-22","924:completion:24-70","924:completion:72-97","924:completion:102-200","924:completion:202-253","924:completion:255-304","924:completion:309-368","924:completion:370-394","924:completion:396-419","924:completion:424-437"},["opening"]="Ak'Zeloth's power stone could sever the altar's connection to the Legion. Its strength would expire, making the climb to Dreadmist's cave urgent.",["pending"]="{actor} planned to disrupt the seed before the stone expires.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} completed the altar task and returned to Ak'Zeloth.",["sourceHash"]="bb14e3a38d2959dec0778ebe96fe8967905e13073f1f2f900cc39e5a5eee5c47",["sourceRaceMask"]="178",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
