[952]={["atomIDs"]={"952:description:1-195","952:description:200-318","952:description:320-357","952:description:359-441","952:objective:1-95"},["opening"]="Fandral sent his own message onward to Onu at Darkshore's Grove of the Ancients. News from the Oracle Glade had reached him, while the Ancient of Lore still awaited his reply.",["pending"]="{actor} planned to deliver Fandral's message to Onu.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered Fandral's message to Onu.",["sourceClassMask"]="?",["sourceHash"]="374fc977e3938c7992d81f819926d848d6583b9a3233f1392944e180ef92145d",["sourceRaceMask"]="77",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
