[958]={["atomIDs"]={"958:description:5-30","958:description:35-72","958:description:74-161","958:description:163-283","958:description:288-417","958:description:419-483","958:objective:1-65"},["baseOverrideRevision"]=1,["baseOverrideSetup"]="Relics among Ameth’Aran’s ruins still carried traces of Highborne magic. Thundris Windweaver sought their removal.",["opening"]="Sentinel reports said Ameth'Aran's Highborne spirits still wielded ancient magical implements. Thundris wanted seven of those relics recovered for destruction from the ruins south of Auberdine.",["pending"]="{actor} meant to recover seven Highborne Relics for Thundris.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered seven Highborne Relics to Thundris Windweaver.",["sourceHash"]="59074a550ae016bf9815327728aee076cd6e5a60835ea39b57f56de9b7ad256a",["sourceRaceMask"]="77",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[959]={["aftermath"]="Bigglefuzz expected to keep his job after the bottle's return. He intended to deliver the recovered gift to Gazlowe immediately.",["atomIDs"]={"959:description:1-5","959:description:10-45","959:description:47-97","959:description:99-109","959:description:111-136","959:description:138-229","959:description:231-272","959:description:277-391","959:description:393-434","959:description:436-463","959:description:468-505","959:objective:1-145"},["endingAtomIDs"]={"959:completion:1-7","959:completion:9-51","959:completion:53-109","959:completion:114-127","959:completion:129-147"},["opening"]="An overloaded unloading job sent crates tumbling at Ratchet. In the confusion Magglish stole a bottle of aged port, and Bigglefuzz stopped his pursuit at the entrance to Wailing Caverns.",["pending"]="{actor} meant to recover the 99-Year-Old Port from Mad Magglish.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} returned the 99-Year-Old Port to Crane Operator Bigglefuzz.",["sourceClassMask"]="?",["sourceHash"]="931a04bca7387387ba15444b80098009bdfb5f025f8d01a3a15dddd921b70225",["sourceMapID"]="?",["sourceRaceMask"]="?",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[963]={["atomIDs"]={"963:description:1-143","963:description:148-252","963:description:254-343","963:description:345-389","963:description:394-442","963:description:444-472","963:objective:1-99"},["opening"]="Cerellean believed Anaya died with Ameth'Aran thousands of years ago, until he saw her spirit among the ruins. Unable to face destroying her himself, he asked another to free her and return her pendant.",["pending"]="{actor} would undertake the task for Anaya's spirit and bring her pendant to Cerellean.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} completed the assignment to free Anaya Dawnrunner's spirit and delivered her pendant to Cerellean.",["sourceHash"]="d328a7552bfcaa92f52e5c174e007eeb46fe2983032d9190dac75216eef75e91",["sourceRaceMask"]="77",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[964]={["aftermath"]="Dithers undertook to temper the bones and named a Tanaris smith as the likely source of a mold.",["atomIDs"]={"964:description:1-48","964:description:51-188","964:description:191-308","964:description:313-343","964:description:346-397","964:description:400-498","964:objective:1-86"},["endingAtomIDs"]={"964:completion:1-17","964:completion:19-166","964:completion:171-231","964:completion:233-330","964:completion:332-395"},["opening"]="Dithers described a key forged from skeletons, reinforced with metal and made functional by a signet. The first stage required bone fragments before any mold or enchantment could be prepared.",["pending"]="{actor} planned to gather fifteen skeletal fragments.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} brought the fragments to Dithers.",["sourceHash"]="697ceeeaf09c934990978124537a152b6e158f7f2d5ae7dc346d601ffc40d427",["sourceRaceMask"]="178",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[968]={["atomIDs"]={"968:description:1-94","968:description:99-114","968:description:119-292","968:description:297-402","968:description:405-433","968:description:438-504","968:objective:1-85"},["opening"]="A worn book described sinister worship and sacrifices beneath its ominous title. Its inside cover named Gerrig Bonegrip's shop in Ironforge, suggesting where the volume might be sold back.",["pending"]="{actor} meant to bring The Powers Below to Gerrig Bonegrip.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered the book The Powers Below to Gerrig Bonegrip.",["sourceHash"]="556eaa5c2eb291ea109db4f951f8bad439cae5c894bbaccad736abb9b3619399",["sourceRaceMask"]="77",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[969]={["aftermath"]="Mau'ari began making the promised charm.",["atomIDs"]={"969:description:1-77","969:description:79-99","969:description:104-115","969:description:117-167","969:description:169-264","969:description:266-313","969:description:318-381","969:objective:1-64"},["endingAtomIDs"]={"969:completion:1-11","969:completion:13-44","969:completion:46-59"},["opening"]="Mau'ari sought reflective shards from the southern canyon for a charm. The frost giants sometimes carried them, though deposits could also be gathered from the ground.",["pending"]="{actor} planned to collect four frostmaul shards.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered the shards to Mau'ari.",["sourceHash"]="14b9d31c0ac3e732e272d74a3d213837e9a8df210af375a4834d633cf7322e0d",["sourceRaceMask"]="?",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[971]={["atomIDs"]={"971:description:1-34","971:description:37-45","971:description:48-61","971:description:64-130","971:description:135-249","971:description:252-301","971:description:304-365","971:description:370-413","971:description:416-449","971:description:452-469","971:description:471-483","971:objective:1-84"},["opening"]="Bonegrip collected old lore for purposes extending beyond ordinary scholarship. Rumor placed the Lorgalis Manuscript among Blackfathom's lost elven knowledge, a find he promised to remember into ominous future days.",["pending"]="{actor} intended to recover the Lorgalis Manuscript for Bonegrip.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered the Lorgalis Manuscript to Gerrig Bonegrip.",["sourceClassMask"]="?",["sourceHash"]="912350310fbe46d8f6ddfca4a3d2c39015ce73e69bf75e0a91f29fa03d758c71",["sourceMapID"]="?",["sourceRaceMask"]="77",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[973]={["atomIDs"]={"973:description:1-17","973:description:19-47","973:description:49-176","973:description:181-299","973:objective:1-72"},["opening"]="Delgren recognized Ilkrud Magthrull as a powerful warlock at Fire Scar Shrine in southwestern Ashenvale. The threat now merited more than watchfulness, and Ilkrud's tome was the evidence Delgren wanted recovered.",["pending"]="{actor} would obtain Ilkrud Magthrull's Tome for Delgren.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered Ilkrud Magthrull's Tome to Delgren the Purifier.",["sourceHash"]="9eb1fb71cdeaa2997be301118be536df63ac07c30d5c28faf4e5cec139d5f73b",["sourceRaceMask"]="77",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[974]={["aftermath"]="Krakle saw a correlation between volcanic temperature and the springs. He still needed to check his heat-transfer equations, preserving the result as a supported direction for further work.",["atomIDs"]={"974:description:1-51","974:description:53-82","974:description:87-208","974:description:210-324","974:description:326-374","974:description:379-472","974:objective:1-80","974:objective:85-167","974:objective:169-212"},["endingAtomIDs"]={"974:completion:1-102","974:completion:104-231","974:completion:233-238"},["opening"]="Krakle wondered whether Fire Plume Ridge heated the nearby springs. His thermometer could test that idea in degrees Kraklenheit, but finding the hottest point required comparing readings across the volcano.",["pending"]="{actor} intended to find Fire Plume Ridge's hottest area with Krakle's thermometer.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} completed the hottest-area survey of Fire Plume Ridge for Krakle.",["sourceClassMask"]="?",["sourceHash"]="5990713b2038ba5fd950a9963446397ec58af950c5a0944aad022f57250a8129",["sourceRaceMask"]="?",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[975]={["atomIDs"]={"975:description:1-64","975:description:69-163","975:description:165-221","975:description:223-233","975:description:238-304","975:description:306-388","975:description:393-425","975:objective:1-75"},["opening"]="Before releasing the charm, Mau'ari explained its condition: it had to be carried for the special finds called E'ko to appear. Those finds could then be brought back to her.",["pending"]="{actor} meant to wait for the charm's preparation.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} returned to Mau'ari for the charm.",["sourceHash"]="12d91e39e928a0b210aabc92c2b19e7de589f7ce3997b7db06bff8d95e68a838",["sourceRaceMask"]="?",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[976]={["atomIDs"]={"976:description:1-126","976:description:128-256","976:description:261-320","976:description:322-407","976:objective:1-101"},["opening"]="Feero had to carry Delgren's messages and supplies toward Auberdine. He feared both the forest's enemies and the loss of the information he bore, so the journey called for protection.",["pending"]="{actor} would guard Feero through Ashenvale and report back to Delgren.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} completed Feero's escort through Ashenvale and spoke with Delgren.",["sourceHash"]="b09b9dc1945bebae45715428817aeb891cf95d14d2ae148ca9bc0e3049e62139",["sourceRaceMask"]="77",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[977]={["aftermath"]="Umi prepared to attach them and anticipated showing the finished creation to her friends.",["atomIDs"]={"977:description:1-94","977:description:96-114","977:description:116-125","977:description:130-235","977:description:237-287","977:description:289-364","977:description:369-450","977:objective:1-64"},["endingAtomIDs"]={"977:completion:1-32","977:completion:34-80","977:completion:85-92"},["opening"]="Umi's covering was ready, but the mechanical creature still lacked horns. Only two pristine examples from the largest yeti would meet the final design.",["pending"]="{actor} intended to recover two unbroken horns.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} supplied Umi with the pristine horns.",["sourceHash"]="c68b7801eb43a383a5056dd14e2b7d6b8bff71e5d09273fbdb7accf96f7b6f3f",["sourceRaceMask"]="?",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[978]={["atomIDs"]={"978:description:1-84","978:description:86-100","978:description:102-234","978:description:239-340","978:description:342-384","978:description:386-419","978:description:421-510","978:objective:1-104"},["opening"]="Hinterlands feathers showed magical qualities that Erelas thought inherent to wildkin. Dropped feathers from Winterspring could reveal whether the snowy land's population shared the same mystery.",["pending"]="{actor} would collect ten Moontouched Feathers from Winterspring for Erelas.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered ten Moontouched Feathers to Erelas Ambersky.",["sourceHash"]="4a86199d282aa70df4145cf1d7ae803ae21e168beaacb5e7bd747437f1024f71",["sourceRaceMask"]="77",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[979]={["atomIDs"]={"979:description:1-95","979:description:97-188","979:description:193-299","979:description:301-359","979:objective:1-39"},["opening"]="Erelas recognized the same enchantment in the new feathers but still lacked an explanation. His colleague Ranshalla was observing wildkin in eastern Winterspring and might have found another part of the answer.",["pending"]="{actor} intended to find Ranshalla in eastern Winterspring.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} reached Ranshalla in eastern Winterspring.",["sourceHash"]="dc1cb6e0067f04427c71765048065409e8672a81564056c16cb9d6a0ffb64a0d",["sourceRaceMask"]="77",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[980]={["atomIDs"]={"980:description:1-97","980:description:99-162","980:description:164-183","980:description:188-285","980:description:287-368","980:description:373-420","980:description:422-435","980:objective:1-53"},["bridge"]="The temperature readings had reached Krakle and supported a volcanic link to the local springs. Winterspring offered a contrasting puzzle: hot pools without a nearby volcano, where Donova Snowden was staying.",["bridgeFrom"]=974,["bridgeReplacesSetup"]=true,["opening"]="Winterspring's hot pools troubled Krakle's volcanic explanation: there were no volcanoes near them. Donova Snowden stayed by those northern springs and offered a new direction for the inquiry.",["pending"]="{actor} planned to speak with Donova Snowden in Winterspring.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} spoke with Donova Snowden at the Winterspring springs.",["sourceClassMask"]="?",["sourceHash"]="96309c1de3687bffcdbdb2f7184c5b9c8f2cad95178ee34c6f2f9b63c6e1931c",["sourceRaceMask"]="?",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[981]={["atomIDs"]={"981:description:1-69","981:description:71-207","981:objective:1-47"},["opening"]="Balthule sent the final report back to Delgren. His message named Athrikus Narassin's defeat and the scattering of the Dark Strand cult as the news to be delivered.",["pending"]="{actor} meant to bring Balthule's report to Delgren.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered the report to Delgren the Purifier at Maestra's Post.",["sourceHash"]="06cb1cec25fb68fa69541bb244e5cdff3a7f490564d4b6842a66f381a23f1805",["sourceRaceMask"]="77",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[982]={["atomIDs"]={"982:description:1-101","982:description:104-212","982:description:215-283","982:description:288-394","982:description:397-502","982:objective:1-100","982:objective:103-190"},["baseOverrideRevision"]=1,["baseOverrideSetup"]="Two wrecked ships off Darkshore held the effects of captains who had not returned. Gorbold Steelhand sought their lockboxes for the surviving crews.",["opening"]="The Silver Dawning and Mist Veil lay north of Auberdine after murloc attacks. Their captains died, but the logs and effects remained in lockboxes below; Gorbold sought those remnants for the surviving crews.",["pending"]="{actor} meant to recover both wrecks' lockboxes for Gorbold.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered the Silver Dawning's Lockbox and the Mist Veil's Lockbox to Gorbold Steelhand.",["sourceHash"]="7aab55bfcb887d5bf6a5b6239927aea6f301b0ce9328f73efd2f239946b5c56e",["sourceRaceMask"]="77",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[983]={["atomIDs"]={"983:description:1-4","983:description:6-51","983:description:53-84","983:description:89-154","983:description:156-206","983:description:211-288","983:description:290-380","983:description:382-419","983:description:421-461","983:description:463-496","983:description:498-511","983:objective:1-53"},["opening"]="Wizbang's distant-speaking buzzboxes required constant maintenance. He placed each near creatures carrying its repair materials; the malfunctioning box south of Auberdine needed six crawler legs.",["pending"]="{actor} would place six Crawler Legs in Buzzbox 827.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} supplied Buzzbox 827 with six Crawler Legs.",["sourceHash"]="b040ea8bcaa26bb9c184e3faf495df2b61c4e36dd2784e0c1219144300a5b211",["sourceRaceMask"]="77",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[984]={["atomIDs"]={"984:description:1-152","984:description:154-162","984:description:167-273","984:description:275-351","984:description:353-439","984:objective:1-78"},["opening"]="Terenthis had seen hints of Darkshore's corruption and wanted to prevent another atrocity like those in Teldrassil. Investigating a furbolg camp might establish how far the danger had spread.",["pending"]="{actor} intended to find a corrupted furbolg camp and report to Terenthis.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} completed the camp-scouting assignment and returned to Terenthis.",["sourceHash"]="84917be46c1c877e054f88b4d9d34f4a29954a156ac4fa857da6dbc849a9c48f",["sourceRaceMask"]="77",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[985]={["atomIDs"]={"985:description:1-54","985:description:56-103","985:description:108-191","985:description:196-319","985:description:321-366","985:description:368-427","985:objective:1-84"},["opening"]="Terenthis identified the Blackwood camp south of Auberdine as the greatest immediate threat. He now asked for direct action against its pathfinders and windtalkers.",["pending"]="{actor} would confront eight Blackwood Pathfinders and five Windtalkers.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} completed the assignment against eight Blackwood Pathfinders and five Windtalkers and returned to Terenthis.",["sourceHash"]="0f1f0c1d199ff92d8d8359b5a81bf193a58c41d7445918e837b29fb3d550212e",["sourceRaceMask"]="77",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[986]={["atomIDs"]={"986:description:1-54","986:description:56-122","986:description:124-255","986:description:260-379","986:description:381-473","986:objective:1-72"},["opening"]="The search for Grimclaw's master required protection from Darkshore's creatures. Terenthis could make a magical cloak, but needed five fine pelts from moonstalker sires or matriarchs in the southern woods.",["pending"]="{actor} meant to bring five Fine Moonstalker Pelts to Terenthis.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered five Fine Moonstalker Pelts to Terenthis.",["sourceHash"]="dc2d4568b57915a77e6bac628b15fc11516599c581c74e6499a05259fd95cd4d",["sourceRaceMask"]="77",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[990]={["atomIDs"]={"990:description:1-88","990:description:90-181","990:description:186-306","990:objective:1-35"},["opening"]="Selarin sent aid south to Raene Wolfrunner in Astranaar. Ashenvale's corruption gave the meeting a purpose beyond travel: Raene needed help easing its hold on the forest.",["pending"]="{actor} intended to find Raene Wolfrunner in Ashenvale.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} reached Raene Wolfrunner in Ashenvale.",["sourceHash"]="2a3d5d086d83f57cd966c91eb71bc8f912298f98de7df2a876261710b147f272",["sourceRaceMask"]="77",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[991]={["atomIDs"]={"991:description:1-103","991:description:108-242","991:description:247-310","991:description:315-428","991:description:430-480","991:description:485-511","991:objective:1-26"},["opening"]="Raene's friend Teronis had not returned from seeking a gem for an old wizard's rod. He hoped the artifact might curb furbolg attacks and last spoke of the shrine at Lake Falathim.",["pending"]="{actor} planned to search for Teronis in Ashenvale.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} found Teronis at the end of the search.",["sourceHash"]="445f7d6761fbf3e74ac465a73471d402236e96e64c99d9bd07aeca828fc25a57",["sourceRaceMask"]="77",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[992]={["atomIDs"]={"992:description:1-117","992:description:122-206","992:description:209-300","992:description:305-393","992:description:396-442","992:description:445-496","992:objective:1-75","992:objective:78-191"},["opening"]="Nomads' seizure of the wells had driven the Gadgetzan Water Company to search for other sources. Fizzledowser's dowsing widget could sample the pool near Sandsorrow Watch, within sight of the trolls.",["pending"]="{actor} meant to sample the Sandsorrow pool and return the tapped widget.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered the tapped dowsing widget to Fizzledowser after completing the water sample.",["sourceClassMask"]="?",["sourceHash"]="862dfe2f6daf4c3f37b5d27b08a2ed55b6b4024d32a0a0872605727981f8319a",["sourceRaceMask"]="?",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[993]={["atomIDs"]={"993:description:1-26","993:description:28-60","993:description:62-92","993:description:97-170","993:description:172-264","993:description:269-349","993:description:351-402","993:description:404-488","993:objective:1-70"},["opening"]="The cloak was ready, though its magic might last only five minutes. Grimclaw waited by the road to point toward his master's cave, where Volcor needed to receive the enchantment.",["pending"]="{actor} intended to find Volcor and give him the Enchanted Moonstalker Cloak.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} found Volcor and delivered the Enchanted Moonstalker Cloak.",["sourceHash"]="62be32ceec931fb775565a953d8d58c4fd54b316f55409986726972278191ecd",["sourceRaceMask"]="77",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
